INPUT.ONLOSTFOCUS:
if coalesce((select kkvalobavezan from roba where robaid = @@robaid ),0) =1 and coalesce((select kkvalobavezan from skladiste where skladisteid = @@skladisteid),0) = 1 and ( @@kolicina <> @@oldkolicina )
									begin exec spmpDajKontigente @action = 11 , @robaid = @@robaid , @skladisteid = @@skladisteid, @kolicina = @@kolicina, @oldkolicina = @@oldkolicina, @operateriid = @@operateriid, @maloprodajadetid = @@stavke, @kontrola = 1 end
								 #if coalesce((select kkvalobavezan from roba where robaid = @@robaid ),0) =1 and coalesce((select kkvalobavezan from skladiste where skladisteid = @@skladisteid),0) = 1 and (@@kolicina <> @@oldkolicina or (select kkvalglaid from maloprodajadet where maloprodajadetid = @@stavke) is null ) begin select   'KONTIGENTI' as form end
